#!/usr/bin/env ruby
# frozen_string_literal: true
def apply_all(*nums, &block)
  nums.map(&block)
end
puts apply_all(1, 2, 3) { |n| n**2 }.inspect

square = ->(x) { x * x }
puts square.call(5)

def factorial(n)
  n <= 1 ? 1 : n * factorial(n - 1)
end
puts factorial(5)

def find_user(id, **options)
  { id: id, role: options.fetch(:role, "guest") }
end
puts find_user(1, role: "admin").inspect

def with_block
  return "没有块" unless block_given?
  yield 42
end
puts with_block { |n| "块收到 #{n}" }

#!/usr/bin/env ruby
# frozen_string_literal: true

class Point
  attr_reader :x, :y
  def initialize(x, y)
    @x = x
    @y = y
  end
  def move(dx, dy)
    @x += dx
    @y += dy
    self
  end
  def to_s
    "(#{@x}, #{@y})"
  end
end

point = Point.new(1, 2)
puts point.move(3, 4)
puts point.x
puts point.inspect

#!/usr/bin/env ruby
# frozen_string_literal: true
class Cart
  def initialize(&discount)
    @items = []
    @discount = discount || ->(total) { total }
  end
  def add(price)
    @items << price
    self
  end
  def total
    @discount.call(@items.sum)
  end
end
cart = Cart.new { |total| total * 0.9 }
cart.add(100).add(200)
puts format("折后: %.2f", cart.total)
