#!/usr/bin/env ruby
# frozen_string_literal: true

require "optparse"

options = { count: 1, verbose: false }
OptionParser.new do |opts|
  opts.banner = "用法: ruby wc.rb [options] [file]"
  opts.on("-c", "--count N", Integer, "处理行数") { |n| options[:count] = n }
  opts.on("-v", "--verbose", "输出每一行") { options[:verbose] = true }
  opts.on("-h", "--help", "显示帮助") { puts opts; exit }
end.parse!

file = ARGV.first
lines = file ? File.readlines(file) : ARGF.readlines
lines.first(options[:count]).each_with_index do |line, i|
  puts "#{i + 1}: #{line.chomp}" if options[:verbose]
end
puts "共读取 #{lines.size} 行"

